import * as T from './vendor/three.module.min.js';
import {createEnergy,ENERGY_PRESETS}from './energy.mjs';
import {createParticleEffect}from './vfx-presets.mjs';
import {FX,AURAS}from'./world.mjs';
export function createEffects(createCanvas){const textures=new Map();
 function texture(kind){if(textures.has(kind))return textures.get(kind);let canvas=createCanvas();canvas.width=canvas.height=128;let g=canvas.getContext('2d');g.clearRect(0,0,128,128);
 const glow=(x,y,r,a)=>{let grad=g.createRadialGradient(x,y,0,x,y,r);grad.addColorStop(0,'rgba(255,255,255,'+a+')');grad.addColorStop(.45,'rgba(255,255,255,'+(a*.48)+')');grad.addColorStop(1,'rgba(255,255,255,0)');g.fillStyle=grad;g.fillRect(x-r,y-r,r*2,r*2)};
 if(kind==='flame'){g.save();g.translate(64,79);g.scale(.48,1);glow(0,-15,49,.9);glow(0,7,25,1);g.restore()}else if(kind==='cloud'){for(let i=0;i<12;i++){let a=i*2.39996,r=10+(i%4)*6;glow(64+Math.cos(a)*r,64+Math.sin(a)*r,23+(i%3)*5,.14)}glow(64,64,52,.12)}
 else if(kind==='streak'){g.save();g.translate(64,64);g.scale(.3,1);glow(0,0,62,1);g.restore()}
 else if(kind==='flake'){glow(64,64,32,.5);g.strokeStyle='#ffffff';g.lineWidth=3;g.beginPath();for(let i=0;i<6;i++){let a=i*Math.PI/3;g.moveTo(64,64);g.lineTo(64+Math.cos(a)*28,64+Math.sin(a)*28)}g.stroke()}
 else if(kind==='cross'){glow(64,64,50,.45);g.fillStyle='#ffffff';g.fillRect(56,35,16,58);g.fillRect(35,56,58,16)}
 else{glow(64,64,60,1);if(kind==='spark'){g.save();g.translate(64,64);g.scale(.12,1);glow(0,0,62,1);g.restore();g.save();g.translate(64,64);g.scale(1,.12);glow(0,0,62,.8);g.restore()}}
 let tex=new T.CanvasTexture(canvas);tex.colorSpace=T.SRGBColorSpace;textures.set(kind,tex);return tex}

 function build(effect,aura,body){let group=new T.Group(),particles=null,ring=null,shield=null;let e=effect?.kind&&FX[effect.kind]?effect:null,a=aura?.enabled&&AURAS[aura.kind]?aura:null;let energy=a&&(ENERGY_PRESETS[a.kind]||a.kind==='flame')?createEnergy(a,body,texture('soft')):null;if(energy)group.add(energy.group);let fire=e?createParticleEffect(e,texture):null;if(fire){group.add(fire.group);e=null}if(a&&!energy){let radius=a.radius||1.2;ring=new T.Mesh(new T.RingGeometry(radius*.9,radius,64),new T.MeshBasicMaterial({color:a.color||'#9abfff',transparent:true,opacity:.7,depthWrite:false,side:T.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.y=.04;group.add(ring);if(['shield','holy'].includes(a.kind)){shield=new T.Mesh(new T.SphereGeometry(radius,20,12),new T.MeshBasicMaterial({color:a.color||'#9abfff',transparent:true,opacity:.12,wireframe:a.kind==='shield',depthWrite:false}));shield.position.y=radius*.7;shield.scale.y=1.15;group.add(shield)}if(a.kind==='runes')for(let i=0;i<12;i++){let rune=new T.Mesh(new T.BoxGeometry(.08,.02,.22),ring.material);rune.position.set(Math.cos(i*Math.PI/6)*radius,.05,Math.sin(i*Math.PI/6)*radius);rune.rotation.y=-i*Math.PI/6;group.add(rune)}}
 return{group,update(time,camera,opacity=1){if(fire)fire.update(time,camera,opacity);if(energy)energy.update(time,camera,opacity);if(a&&!energy){let pulse=.85+.15*Math.sin(time*2.5);ring.material.opacity=opacity*(a.intensity||.7)*pulse;let s=['pulse','flame','holy'].includes(a.kind)?1+.12*Math.sin(time*2):1;ring.scale.setScalar(s);ring.rotation.z=a.kind==='runes'?time*.3:0;if(shield){shield.material.opacity=opacity*.13*pulse;shield.rotation.y=time*.3}if(a.kind==='flame'){ring.material.color.setHSL(.06+.04*Math.sin(time*3),.9,.6);ring.scale.setScalar(1+.08*Math.sin(time*7))}}},dispose(){if(fire){group.remove(fire.group);fire.dispose()}if(energy){group.remove(energy.group);energy.dispose()}let gs=new Set(),ms=new Set();group.traverse(o=>{if(o.geometry)gs.add(o.geometry);if(o.material)ms.add(o.material)});for(let g of gs)g.dispose();for(let m of ms)m.dispose()}}}
 return{build,burst(config){return createParticleEffect(config,texture)},dispose(){for(let t of textures.values())t.dispose()}};
}
